CREATE TABLE IF NOT EXISTS org_branding(org_id TEXT PRIMARY KEY REFERENCES organizations(id), app_name TEXT NOT NULL DEFAULT 'Wrangnarok' CHECK(length(app_name) BETWEEN 1 AND 80), primary_color TEXT NOT NULL DEFAULT '#F45D0B' CHECK(length(primary_color) BETWEEN 4 AND 9), accent_color TEXT NOT NULL DEFAULT '#F59E0B' CHECK(length(accent_color) BETWEEN 4 AND 9), logo_content_type TEXT NOT NULL DEFAULT '' CHECK(length(logo_content_type) <= 128), logo_size INTEGER NOT NULL DEFAULT 0 CHECK(logo_size BETWEEN 0 AND 5242880), logo_sha256 TEXT NOT NULL DEFAULT '' CHECK(length(logo_sha256) IN (0, 64)), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_profiles(org_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL CHECK(length(user_id) BETWEEN 1 AND 320), display_name TEXT NOT NULL DEFAULT '' CHECK(length(display_name) <= 80), theme TEXT NOT NULL DEFAULT 'system' CHECK(theme IN ('light', 'dark', 'system')), avatar_content_type TEXT NOT NULL DEFAULT '' CHECK(length(avatar_content_type) <= 128), avatar_size INTEGER NOT NULL DEFAULT 0 CHECK(avatar_size BETWEEN 0 AND 2097152), avatar_sha256 TEXT NOT NULL DEFAULT '' CHECK(length(avatar_sha256) IN (0, 64)), updated_at TEXT NOT NULL, PRIMARY KEY(org_id, user_id));
CREATE INDEX IF NOT EXISTS user_profiles_org ON user_profiles(org_id, user_id);
